    "PRICING_BASE_URL", "http://pricing-v2.internal:8081/api/v2/price"
).rstrip("/")


def get_price(sku: str) -> float:
    """Fetch the current price for *sku* from the internal pricing service."""
    key = os.environ.get("PRICING_API_KEY")
    if not key:
        raise RuntimeError("PRICING_API_KEY is required to access the pricing service")

    request = urllib.request.Request(
        f"{BASE}/{urllib.parse.quote(sku, safe='')}",
        headers={"X-Pricing-Key": key},
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        payload = json.load(response)

    # V2 calls the monetary value ``amount``. Accepting ``price`` keeps the
    # client compatible with installations that still expose the V1 schema.
    return float(payload.get("amount", payload.get("price")))


def get_total(skus: list[str]) -> float:
    return sum(map(get_price, skus))
