).rstrip("/")


def get_price(sku: str) -> float:
    """Fetch the current price for *sku* from the internal pricing service."""
    key = os.environ.get("PRICING_API_KEY")
    headers = {"X-Pricing-Key": key} if key else {}
    request = urllib.request.Request(
        f"{BASE}/{urllib.parse.quote(sku, safe='')}", headers=headers
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        payload = json.load(response)

    for field in ("amount", "price", "unit_price"):
        if field in payload:
            return float(payload[field])
    raise ValueError("pricing response does not contain a price")


def get_total(skus: list[str]) -> float:
    return sum(map(get_price, skus))

